func init() {
	func() {
		defer func() {
			if r := recover(); r != nil {
				fmt.Fprintln(os.Stderr, "gowt/internal/cocoa: deferred init DisplayAlign:", r)
			}
		}()
		var cond232 int32
		if cocoa.CPTR_SIZEOF == 4 {
			cond232 = 2
		} else {
			cond232 = 3
		}
		DisplayAlign = cond232
	}()
	func() {
		defer func() {
			if r := recover(); r != nil {
				fmt.Fprintln(os.Stderr, "gowt/internal/cocoa: deferred init Display static{}:", r)
			}
		}()
		DeviceDeviceFinder = jrt.NewRunnable(func() {
			var device *Device = upcastDisplayToDevice(DisplayGetCurrent())
			if device == (nil) {
				device = upcastDisplayToDevice(DisplayGetDefault())
			}
			DisplaySetDevice(device)
		})
	}()
	func() {
		defer func() {
			if r := recover(); r != nil {
				fmt.Fprintln(os.Stderr, "gowt/internal/cocoa: deferred init Display static{}:", r)
			}
		}()
		DisplayConfigureSystemOptions()
	}()
}
